CREATE TABLE IF NOT EXISTS "identity_users" (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, status varchar(64) NOT NULL DEFAULT 'draft', code varchar(160), name varchar(255), description text, data jsonb NOT NULL DEFAULT '{}'::jsonb, version integer NOT NULL DEFAULT 1, is_archived boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT uq_identity_users_tenant_code UNIQUE (tenant_id, code));
