ALTER TABLE "identity_users" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "identity_users" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "identity_users_tenant_isolation" ON "identity_users";
CREATE POLICY "identity_users_tenant_isolation" ON "identity_users" USING (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid);
